package com.bank.slo;

import java.util.logging.Logger;

// Derives the error budget from an SLO and tracks how much is consumed.
public class ErrorBudget {
    private static final Logger log = Logger.getLogger(ErrorBudget.class.getName());

    private final long totalRequestsInWindow;
    private final long allowedFailures;    // the budget = (1 - SLO) * total
    private long consumedFailures = 0;

    public ErrorBudget(double sloPercent, long totalRequestsInWindow) {
        this.totalRequestsInWindow = totalRequestsInWindow;
        double budgetFraction = (100.0 - sloPercent) / 100.0;   // e.g. 0.001 for 99.9%
        this.allowedFailures = Math.round(budgetFraction * totalRequestsInWindow);
        log.info(() -> String.format("Budget derived: SLO %.3f%% over %d requests "
                + "=> %d failures allowed this window",
                sloPercent, totalRequestsInWindow, allowedFailures));
    }

    // Spend budget — from an incident or a risky release.
    public void consume(long failures, String cause) {
        consumedFailures += failures;
        log.info(() -> "Consumed " + failures + " failures (" + cause + "); remaining "
                + remaining() + " of " + allowedFailures);
    }

    public long remaining() { return allowedFailures - consumedFailures; }

    public double remainingPercent() {
        return allowedFailures == 0 ? 0.0 : 100.0 * remaining() / allowedFailures;
    }

    public boolean exhausted() { return remaining() <= 0; }
}
