package com.bank.slo;

import java.util.logging.Logger;

// Governs release pace vs reliability work based on remaining error budget.
public class ReleaseGate {
    private static final Logger log = Logger.getLogger(ReleaseGate.class.getName());

    private final ErrorBudget budget;

    public ReleaseGate(ErrorBudget budget) {
        this.budget = budget;
    }

    public enum Decision { RELEASE_FREELY, RELEASE_WITH_CAUTION, FREEZE_RELEASES }

    // Decide whether a release may proceed, and flag a fast burn.
    public Decision evaluate(long recentHourFailures) {
        // Fast-burn detection: consuming a big chunk of the whole budget in one hour.
        if (recentHourFailures > budget.remaining() * 0.5 && !budget.exhausted()) {
            log.severe(() -> "FAST BURN: " + recentHourFailures
                    + " failures in 1h — budget draining rapidly, PAGE + consider rollback");
        }

        if (budget.exhausted()) {
            log.severe("FREEZE: error budget EXHAUSTED — non-essential releases FROZEN. "
                     + "Team redirects to reliability work until budget recovers.");
            return Decision.FREEZE_RELEASES;
        } else if (budget.remainingPercent() < 25) {
            log.warning(() -> String.format("CAUTION: only %.1f%% budget left — "
                    + "ship only low-risk changes, prioritise fixes", budget.remainingPercent()));
            return Decision.RELEASE_WITH_CAUTION;
        } else {
            log.info(() -> String.format("RELEASE FREELY: %.1f%% budget remains — "
                    + "ship features at pace", budget.remainingPercent()));
            return Decision.RELEASE_FREELY;
        }
    }
}
