package com.bank.slo;

import java.util.logging.*;

// Runnable demo: budget burns down through incidents until releases freeze.
public class BudgetDemo {
    private static final Logger log = Logger.getLogger(BudgetDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        ch.setLevel(Level.ALL);
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        log.info("National Bank of India — error budget governance for transfer service");

        // SLO 99.9% over 10,000,000 transfers this window => 10,000 failures allowed.
        ErrorBudget budget = new ErrorBudget(99.9, 10_000_000L);
        ReleaseGate gate = new ReleaseGate(budget);

        // Start of window: full budget — ship freely.
        gate.evaluate(0);

        // A risky feature release causes 3,000 failed transfers.
        budget.consume(3000, "feature release v2.0 regression");
        gate.evaluate(3000);   // still > 25% left

        // A dependency outage burns another 5,000 in one hour — FAST BURN.
        budget.consume(5000, "account-service outage");
        gate.evaluate(5000);   // caution + fast-burn page

        // A final incident exhausts the budget.
        budget.consume(2500, "database failover incident");
        gate.evaluate(1000);   // FREEZE

        log.info("Policy outcome: releases frozen; team now fixes regressions + adds "
               + "resilience until the rolling window restores budget.");
    }
}
